CREATE TABLE public.prep_gestor_regional (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), loja text NOT NULL UNIQUE, gestor text NOT NULL CHECK(length(trim(gestor))>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.prep_gestor_regional TO authenticated;
GRANT ALL ON public.prep_gestor_regional TO service_role;
ALTER TABLE public.prep_gestor_regional ENABLE ROW LEVEL SECURITY;
CREATE POLICY prep_gestor_modulo ON public.prep_gestor_regional FOR ALL TO authenticated USING(public.has_modulo('preparacao-anuncios')) WITH CHECK(public.has_modulo('preparacao-anuncios'));
CREATE TABLE public.prep_dashboard_historico_diario (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), data_referencia date NOT NULL UNIQUE DEFAULT (now() AT TIME ZONE 'America/Sao_Paulo')::date, importacao_id uuid REFERENCES public.prep_importacoes(id), total_ativos integer NOT NULL CHECK(total_ativos>=0), total_pendentes integer NOT NULL CHECK(total_pendentes>=0 AND total_pendentes<=total_ativos), indicadores jsonb NOT NULL, dimensoes jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.prep_dashboard_historico_diario TO authenticated;
GRANT ALL ON public.prep_dashboard_historico_diario TO service_role;
ALTER TABLE public.prep_dashboard_historico_diario ENABLE ROW LEVEL SECURITY;
CREATE POLICY prep_dashboard_ler ON public.prep_dashboard_historico_diario FOR SELECT TO authenticated USING(public.has_modulo('preparacao-anuncios'));
CREATE POLICY prep_dashboard_inserir ON public.prep_dashboard_historico_diario FOR INSERT TO authenticated WITH CHECK(public.has_modulo('preparacao-anuncios'));
CREATE POLICY prep_dashboard_atualizar ON public.prep_dashboard_historico_diario FOR UPDATE TO authenticated USING(public.has_modulo('preparacao-anuncios')) WITH CHECK(public.has_modulo('preparacao-anuncios'));
CREATE INDEX prep_dashboard_importacao_idx ON public.prep_dashboard_historico_diario(importacao_id);
CREATE FUNCTION public.prep_dashboard_limpar_historico() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ DELETE FROM public.prep_dashboard_historico_diario WHERE data_referencia < ((now() AT TIME ZONE 'America/Sao_Paulo')::date - interval '3 months')::date; $$;
REVOKE ALL ON FUNCTION public.prep_dashboard_limpar_historico() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.prep_dashboard_limpar_historico() TO service_role;
CREATE FUNCTION public.prep_dashboard_retencao() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.prep_dashboard_limpar_historico(); RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.prep_dashboard_retencao() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER prep_dashboard_retencao AFTER INSERT OR UPDATE ON public.prep_dashboard_historico_diario FOR EACH STATEMENT EXECUTE FUNCTION public.prep_dashboard_retencao();
DO $$ BEGIN PERFORM cron.schedule('prep-dashboard-retencao','15 6 * * *','select public.prep_dashboard_limpar_historico()'); END $$;